// The demo seed (supabase/seed.sql, generated by `pnpm seed`) must apply on top of every
// migration — `supabase db reset` runs it — and give the NGO dashboard real data.
import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { createTestDb, MIGRATIONS_DIR, type TestDb } from "./harness";

const ADMIN_ID = "00000000-0000-0000-0000-000000000002";
let t: TestDb;

beforeAll(async () => {
  t = await createTestDb();
  await t.db.exec(readFileSync(resolve(MIGRATIONS_DIR, "../seed.sql"), "utf8"));
});
afterAll(async () => t?.close());

describe("demo seed", () => {
  it("creates the NGO, its admin login and 35 student accounts", async () => {
    const r = await t.db.query<{ admins: number; students: number; logins: number; identities: number }>(`
      select
        (select count(*)::int from profiles where role = 'ngo_admin') as admins,
        (select count(*)::int from profiles where role = 'student') as students,
        (select count(*)::int from auth.users) as logins,
        (select count(*)::int from auth.identities) as identities`);
    expect(r.rows[0]).toEqual({ admins: 1, students: 35, logins: 36, identities: 36 });
  });

  it("stores real Mindset answers (personas vary; scores aren't all zero)", async () => {
    const r = await t.db.query<{ personas: number; nonzero: number; post: number }>(`
      select count(distinct persona_id)::int as personas,
             count(*) filter (where (scores->>'plan')::int + (scores->>'know')::int > 0)::int as nonzero,
             count(*) filter (where phase = 'post')::int as post
        from mindset_responses`);
    expect(r.rows[0]!.personas).toBeGreaterThan(1);
    expect(r.rows[0]!.nonzero).toBeGreaterThan(20);
    expect(r.rows[0]!.post).toBeGreaterThan(20);
  });

  it("the admin sees the whole class through RLS and the stats views", async () => {
    const seen = await t.asUser(ADMIN_ID, async (tx) => ({
      students: (await tx.query(`select 1 from profiles where role = 'student'`)).rows.length,
      results: (await tx.query(`select 1 from chapter_results`)).rows.length,
      decisions: (await tx.query(`select 1 from decisions`)).rows.length,
    }));
    expect(seen.students).toBe(35);
    expect(seen.results).toBe(35);
    expect(seen.decisions).toBeGreaterThan(35 * 5);
  });

  const VIEWS = [
    "org_seats_v",
    "org_engagement_v",
    "org_persona_distribution_v",
    "org_learning_gain_v",
    "org_scam_stats_v",
    "org_chapter_stats_v",
    "org_student_detail_v",
  ];

  it("every dashboard stats view returns the admin's class", async () => {
    for (const view of VIEWS) {
      const r = await t.asUser(ADMIN_ID, (tx) => tx.query(`select * from ${view}`));
      expect(r.rows.length, view).toBeGreaterThan(0);
    }
    const detail = await t.asUser(ADMIN_ID, (tx) => tx.query(`select 1 from org_student_detail_v`));
    expect(detail.rows).toHaveLength(35);
  });

  it("stats views report the true numbers (no join fan-out)", async () => {
    const seats = await t.asUser(ADMIN_ID, (tx) =>
      tx.query<Record<string, number | string>>(`select * from org_seats_v`),
    );
    expect(seats.rows[0]).toMatchObject({
      total_codes_generated: 40,
      pending_codes: 3,
      active_codes: 35,
      expired_codes: 2,
      total_students: 35,
      linked_personal_learners: 0,
    });
    const engagement = await t.asUser(ADMIN_ID, (tx) =>
      tx.query<Record<string, number>>(`select total_students, total_playthroughs from org_engagement_v`),
    );
    expect(engagement.rows[0]).toMatchObject({ total_students: 35, total_playthroughs: 35 });
    const chapters = await t.asUser(ADMIN_ID, (tx) =>
      tx.query<Record<string, number>>(`select attempts_count from org_chapter_stats_v`),
    );
    expect(chapters.rows[0]).toMatchObject({ attempts_count: 35 });
  });

  it("stats views return nothing to students (they run with the owner's rights, so they must filter)", async () => {
    const student = "00000000-0000-0000-0001-000000000002";
    for (const view of VIEWS) {
      const r = await t.asUser(student, (tx) => tx.query(`select * from ${view}`));
      expect(r.rows, view).toHaveLength(0);
    }
  });

  it("a student sees only their own data", async () => {
    const student = "00000000-0000-0000-0001-000000000001";
    const seen = await t.asUser(student, (tx) => tx.query(`select 1 from chapter_results`));
    expect(seen.rows).toHaveLength(1);
  });
});
